// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { ArrowDownUpIcon, CopyIcon, SaveIcon, XIcon } from 'lucide-react'
import type { ReactNode } from 'react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import { esc } from '../_shared'
import { BAD_HEX, CAPTIONS, HEX, HEX_ERROR, KINDS, OUTPUTS, TEXT } from './script'

const RAIN = Array.from({ length: 14 }, (_, index) =>
  Array.from({ length: 12 }, (_, row) => ((index * 7 + row * 3) % 5 > 1 ? '1' : '0')).join('\n'),
)
const ACTIVE = { backgroundColor: 'rgba(255,255,255,0.1)', borderColor: 'rgba(255,255,255,0)' }
const IDLE = { backgroundColor: 'rgba(255,255,255,0)', borderColor: 'rgba(255,255,255,0.14)' }

const build: Build = ({
  tl,
  q,
  qa,
  pos,
  step,
  final,
  move,
  click,
  type,
  scramble,
  wait,
  cursorOut,
}) => {
  const pill = (index: number, at?: string) => {
    const tab = pos(`tab-${index}`, 0, 0)
    const list = pos('tabs', 0, 0)
    tl.to(
      q('tab-pill'),
      { left: tab.x - list.x, width: tab.w, duration: 0.35, ease: 'power3.inOut' },
      at,
    )
    KINDS.forEach((_, other) =>
      tl.to(
        q(`tab-${other}`),
        { color: other === index ? '#f5f5f7' : 'rgba(245,245,247,0.5)', duration: 0.2 },
        '<',
      ),
    )
  }
  const rain = (at?: string) => {
    tl.fromTo(
      qa('rain-col'),
      { yPercent: -60, opacity: 0 },
      { yPercent: 10, opacity: 0.5, duration: 0.6, stagger: 0.025, ease: 'power1.in' },
      at,
    )
    tl.to(qa('rain-col'), { opacity: 0, duration: 0.35, stagger: 0.02 }, '>-0.3')
  }
  const output = (index: number, at?: string) => {
    const { id, value } = OUTPUTS[index]
    rain(at)
    scramble('output-text', esc(value), {
      at: '<-0.3',
      duration: 0.7,
      chars: id === 'base64' || id === 'hex' ? '01' : 'upperAndLowerCase',
    })
  }

  const first = pos('tab-0', 0, 0)
  const list = pos('tabs', 0, 0)
  tl.set(q('tab-pill'), { left: first.x - list.x, width: first.w }, 0)

  step(0)
  move('input', { ax: 0.3, ay: 0.3, at: 0.2 })
  click('input')
  type('input-text', esc(TEXT), { speed: 0.06 })
  tl.fromTo(
    q('output'),
    { opacity: 0, x: 12 },
    { opacity: 1, x: 0, duration: 0.35, ease: 'power2.out' },
    '>-0.2',
  )
  output(0, '<')

  step(1, '+=0.6')
  KINDS.slice(1).forEach((_, offset) => {
    const index = offset + 1
    move(`tab-${index}`, { duration: 0.45 })
    click(`tab-${index}`)
    pill(index, '<')
    output(index, '<')
    tl.to({}, { duration: 0.35 })
  })

  step(2, '+=0.4')
  move('swap')
  click('swap')
  tl.to(q('input-text'), { text: { value: HEX, delimiter: '' }, duration: 0.5, ease: 'none' }, '<')
  tl.to(q('mode-encode'), { ...IDLE, color: 'rgba(245,245,247,0.6)', duration: 0.2 }, '<')
  tl.to(q('mode-decode'), { ...ACTIVE, color: '#f5f5f7', duration: 0.2 }, '<')
  scramble('output-text', esc(TEXT), { at: '<0.2', duration: 0.8 })
  tl.fromTo(
    q('output-pane-box'),
    { boxShadow: '0 0 0 0px rgba(52,211,153,0.55)' },
    { boxShadow: '0 0 0 8px rgba(52,211,153,0)', duration: 0.7, ease: 'power2.out' },
    '>',
  )

  step(3, '+=0.8')
  move('input', { ax: 0.6, ay: 0.4 })
  click('input')
  type('input-text', BAD_HEX, { at: '>', speed: 0.6 / BAD_HEX.length })
  tl.to(q('output-text'), { opacity: 0, duration: 0.15 }, '>-0.05')
  tl.fromTo(
    q('error'),
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.3, ease: 'power2.out' },
    '<',
  )
  cursorOut('+=0.4')
  final()
  wait(1.4)
}

function Pane({
  label,
  d,
  textD,
  actions,
  children,
}: {
  label: string
  d: string
  textD: string
  actions?: boolean
  children?: ReactNode
}) {
  return (
    <div data-d={d} className="flex min-h-0 flex-1 flex-col">
      <div className="mb-1 flex h-4 items-center justify-between">
        <span className="text-[10px] font-medium text-ink-soft">{label}</span>
        {actions ? (
          <span className="flex gap-1.5 text-muted">
            <SaveIcon className="size-3" />
            <CopyIcon className="size-3" />
            <XIcon className="size-3" />
          </span>
        ) : null}
      </div>
      <div
        data-d={`${d}-box`}
        className="relative min-h-0 flex-1 overflow-hidden rounded-md border border-line-strong bg-canvas/80 p-2"
      >
        {children}
        <p
          data-d={textD}
          className="relative whitespace-pre-wrap break-all font-mono text-[10.5px] leading-[1.6] text-ink"
        />
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="Encoder Decoder encoding one string as Base64, URL, HTML, Unicode and Hex, swapping it back, and explaining a bad hex input"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-2.5">
          <div className="flex items-center gap-2">
            <div
              data-d="tabs"
              className="relative flex rounded-lg border border-line bg-white/[0.03] p-0.5"
            >
              <span
                data-d="tab-pill"
                className="absolute inset-y-0.5 left-0.5 w-12 rounded-md bg-white/10"
              />
              {KINDS.map((kind, index) => (
                <span
                  key={kind.id}
                  data-d={`tab-${index}`}
                  className="relative px-2 py-1 text-[10.5px]"
                  style={{ color: index === 0 ? '#f5f5f7' : 'rgba(245,245,247,0.5)' }}
                >
                  {kind.label}
                </span>
              ))}
            </div>
            <span
              data-d="mode-encode"
              className="rounded-md border px-2 py-1 text-[10.5px]"
              style={{ ...ACTIVE, color: '#f5f5f7' }}
            >
              Encode
            </span>
            <span
              data-d="mode-decode"
              className="rounded-md border px-2 py-1 text-[10.5px]"
              style={{ ...IDLE, color: 'rgba(245,245,247,0.6)' }}
            >
              Decode
            </span>
            <span data-d="swap" className="flex size-6 items-center justify-center text-ink-soft">
              <ArrowDownUpIcon className="size-3.5" />
            </span>
          </div>
          <div className="grid min-h-0 flex-1 grid-cols-2 gap-2.5">
            <Pane label="Input" d="input" textD="input-text" />
            <div data-d="output" className="relative flex min-h-0 flex-col opacity-0">
              <Pane label="Output" d="output-pane" textD="output-text" actions>
                <div className="pointer-events-none absolute inset-0 flex justify-between px-2">
                  {RAIN.map((column, index) => (
                    <span
                      key={index}
                      data-d="rain-col"
                      className="whitespace-pre font-mono text-[9px] leading-[1.25] text-[var(--accent)] opacity-0"
                    >
                      {column}
                    </span>
                  ))}
                </div>
                <div
                  data-d="error"
                  className="absolute inset-x-2 top-2 rounded-md border border-rose/40 bg-rose/10 p-2 text-[10px] leading-snug text-rose opacity-0"
                >
                  {HEX_ERROR}
                </div>
              </Pane>
            </div>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
